UPDATE abt_variabel SET nama = 'INTERVENSI SAMPUL AWAL (OTOMATIS: pihak intervensi dari SIPP, tiga nama sebaris; kosong bila tidak ada)', data_type = 'data_sql', sql_query = 'SELECT CONCAT(''INTERVENSI ('',COUNT(*),'')  '',GROUP_CONCAT(CASE WHEN a.urutan<=3 THEN CONCAT(ELT(a.urutan,''I'',''II'',''III'',''IV'',''V'',''VI'',''VII'',''VIII'',''IX'',''X'',''XI'',''XII'',''XIII'',''XIV'',''XV'',''XVI'',''XVII'',''XVIII'',''XIX'',''XX''),''. '',a.nama) END ORDER BY a.urutan SEPARATOR ''  -  ''),IF(COUNT(*)>3,CONCAT(''  -  dan '',COUNT(*)-3,'' lainnya (lampiran)''),'''')) AS data FROM perkara_pihak3 a WHERE a.perkara_id=#perkara_id# HAVING COUNT(*)>0', locked = 1 WHERE no_var = 5847 AND MD5(CONCAT_WS('|', nama, data_type, IFNULL(sql_query, ''), locked)) = '107e57ab8fb1b0658ea26394ccb2e7b1';
